content.text:
}
.roles .where{font-size:var(--step-small);color:var(--muted)}
.contact-line{margin-top:18px;font-size:var(--step-small);color:var(--muted)}
.contact-side{max-width:330px}
.contact-side h3{font-size:1.125rem;font-weight:500;margin-bottom:16px}
.contact-links{display:flex;flex-direction:column;gap:12px}
.contact-links a{
  font-size:1.0625rem;
  text-decoration:underline;
  text-decoration-thickness:1px;
  text-underline-offset:5px;
  transition:color .2s ease;
}
.contact-links a:hover{color:var(--accent)}
.contact-links .pending{
  margin-left:8px;
  font-size:var(--step-small);
  color:var(--muted);
  text-decoration:none;
  display:inline-block;
}
.contact-side .city{margin-top:22px;font-size:var(--step-small);color:var(--muted);line-height:1.6}
.slots{
  display:grid;
  grid-template-columns:repeat(5,minmax(0,1fr));
  gap:22px;
  margin-top:clamp(48px,6vw,86px);
}
.slot{
  display:block;
  text-decoration:none;
  color:var(--ink);
  padding-top:14px;
  position:relative;
  transition:color .2s ease;
}
.slot::before{
  content:"";
  position:absolute;
  left:0;right:0;top:0;
  height:4px;
  background:var(--surface);
}
.slot:hover .slot-label{color:var(--accent)}
.slot-label{display:block;font-size:1rem;font-weight:500;transition:color .2s ease}
.slot-value{display:block;margin-top:3px;font-size:var(--step-small);color:var(--muted);line-height:1.4}

/* footer */
.footer{padding-top:clamp(56px,7vw,100px);padding-bottom:38px}
.footer .shell{
  display:grid;
  grid-template-columns:1fr auto 1fr;
  gap:18px 28px;
  align-items:baseline;
  font-size:var(--step-small);
  color:var(--muted);
}
.footer .foot-links{display:flex;gap:22px;justify-content:center;flex-wrap:wrap}
.footer a{text-decoration:none;color:var(--ink);transition:color .2s ease}
.footer a:hover{color:var(--accent)}
.footer .year{text-align:right}

/* reveal */
.js [data-reveal]{
  opacity:0;
  transform:translateY(18px);
  transition:opacity .75s cubic-bezier(.22,.61,.36,1),transform .75s cubic-bezier(.22,.61,.36,1);
  transition-delay:var(--d,0ms);
}
.js [data-reveal].in{opacity:1;transform:none}

@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  .js [data-reveal]{opacity:1;transform:none;transition:none}
  .hero-figure img{animation:none}
  .preview{transition:none}
  .btn,.text-link,.site-nav a,.project-link,.read-btn{transition:none}
}

@media (max-width:980px){
  .split{grid-template-columns:minmax(0,1fr);gap:44px}
  .offset{padding-left:var(--gutter)}
  .hero{min-height:0;display:block;padding-top:clamp(24px,4vw,48px)}
  .hero-figure{max-width:520px;justify-self:start;margin-top:40px}
  .preview-sticky{position:static}
  .previews{display:block}
  .preview{
    opacity:1;visibility:visible;
